validator:
function validate(input) {
  const [{ students = [] }] = input;
  for (const [id, , age] of students) {
    if (id === null) return 'student_id cannot be null.';
    if (age === null) return 'age cannot be null.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Piper', 'Georgia', 'Willow', 'Mason', 'Ava', '', 'None', null];
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const students = [];
  for (let i = 0; i < rows; i++) {
    const id = size === 'small' ? Math.floor(rand() * 900) + 1 : i + 1;
    const name = rand() < 0.3 ? null : pick(names);
    students.push([id, name, Math.floor(rand() * 25) + 1]);
  }
  return [{ students }];
}
